-- Deities and Demigods: Asgardian divine servants and monster frameworks.
-- Source: Deities and Demigods (2002), Chapter 6, pp. 199-201, plus official v3.5 revision update.
-- Full printed blocks that do not provide an explicit CR are represented as structured rules rather than inventing a required dnd35_monsters CR.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

WITH desired(slug,name,page,summary,tags,mechanics) AS (VALUES
('dd-quasi-deity-traits-revised','Quasi-Deity Traits (Official 3.5 Revision)','official 3.5 update p. 11',
 'The official revised trait package used by divine-rank-0 servants such as Skirnir, einherjar, and Asgardian giants.',
 '["deities-and-demigods","asgardian","quasi-deity","divine-rank-0","revision-3.5"]',
 '{"divineRank":0,"revision3_5":{"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immortal":true},"supersedesPrinted3_0Package":true,"sourceNote":"The revision explicitly replaces the earlier quasi-deity trait entry; individual creatures may retain separate subtype or racial immunities in addition to this package."}'),

('dd-template-einherjar','Einherjar Template','199-200; official 3.5 update p. 11',
 'An acquired divine-servant template for heroic good humanoid warriors chosen after death to serve the Asgardian gods.',
 '["deities-and-demigods","asgardian","monster-template","einherjar","quasi-deity","revision-3.5"]',
 '{"templateType":"acquired","appliesTo":{"creatureType":"humanoid","alignment":"good","minimumClassLevels":10,"qualifyingClasses":["barbarian","fighter","ranger","paladin"]},"divineRank":0,"size":"unchanged","typeChange":{"type":"outsider","subtypes":["good"],"materialPlaneAddsSubtype":"extraplanar"},"speed":{"landSpeedIncreaseFeet":30},"retainsBaseStatisticsAndAbilities":true,"revision3_5":{"quasiDeityTraits":{"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immortal":true}},"printedExamples":{"count":3,"level":"20th-level characters","races":["dwarf","elf","human"],"challengeRatingEach":20,"organization":"Troop (20-40)","environment":"Asgard","note":"The printed examples also apply to the female warriors of Sif''s hall."},"sourceFidelity":{"printed3_0QuasiDeityTraits":"Included electricity, cold, and acid immunity; fire resistance 20; DR 35/+4; SR 32; immortality.","officialRevision":"Replace the printed quasi-deity package with the revision3_5 package above rather than combining them."}}'),

('dd-asgardian-giant-framework','Asgardian Divine Giants','200-201; official 3.5 update p. 11',
 'Jotunheim frost giants and Muspelheim fire giants are divine-rank-0 outsiders modeled on their Monster Manual counterparts and often possess substantial warrior class training.',
 '["deities-and-demigods","asgardian","giant","quasi-deity","jotunheim","muspelheim","revision-3.5"]',
 '{"regions":{"jotunheim":"frost giants","muspelheim":"fire giants"},"divineRank":0,"guidance":"Use Monster Manual frost-giant and fire-giant concepts with the Deities and Demigods Asgardian adjustments.","typicalClassTraining":"Most have 5 or more levels of barbarian, fighter, or ranger.","revision3_5":{"quasiDeityTraits":{"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immortal":true}},"sourceFidelity":"Do not retain the printed 3.0 DR 35/+4 quasi-deity package after applying the official revision; elemental subtype abilities remain separate."}'),

('dd-jotunheim-frost-giant-sample','Jotunheim Frost Giant Sample','200',
 'The printed divine-rank-0 Jotunheim frost-giant combat example. The source does not provide an explicit CR for this individual block.',
 '["deities-and-demigods","asgardian","monster-stat-block","frost-giant","jotunheim","quasi-deity","revision-3.5"]',
 '{"divineRank":0,"printedClass":"Bbn20","sourceClassHdAnomaly":"The printed header says Bbn20 while the block contains only 20d8 Hit Dice rather than adding 20 barbarian d12s; preserve the source presentation without fabricating additional HD.","creature":{"type":"outsider","sourceSubtypes":["evil","cold"],"size":"Gargantuan","hitDice":"20d8+123","hitPoints":213,"initiative":3,"speedFeet":130,"armorClass":18,"touchAc":5,"flatFootedAc":18,"spaceFeet":20,"reachFeet":20},"attacks":{"greataxe":"+22/+17/+12 melee, Huge masterwork greataxe","greataxeDamage":"2d8+9/19-20/x3","rock":"+11/+6/+1 ranged","rockDamage":"2d6+9"},"specialAttacks":["rock throwing"],"specialQualities":["cold subtype","printed DR 35/+4 and barbarian DR 4/-","darkvision 60 ft.","fast movement","greater rage 6/day","rock catching","uncanny dodge (cannot be flanked, +4 against traps)","quasi-deity traits"],"saves":{"fort":18,"ref":7,"will":8},"abilities":{"str":29,"dex":9,"con":23,"int":10,"wis":10,"cha":12},"skills":{"Climb":19,"Hide":-15,"Intimidate":11,"Intuit Direction":10,"Jump":19,"Listen":12,"Spot":18,"Wilderness Lore":10},"feats":["Alertness","Cleave","Endurance","Great Cleave","Improved Critical (greataxe)","Improved Initiative","Iron Will","Lightning Reflexes","Martial Weapon Proficiency (greataxe)","Power Attack","Quick Draw","Run","Sunder","Toughness","Weapon Focus (greataxe)","Weapon Focus (rock)"],"alignment":"CE","greaterRagePrinted":{"armorClass":16,"hitPoints":333,"greataxeAttack":"+25/+20/+15","greataxeDamage":"2d8+12/19-20/x3","fort":21,"will":11,"str":35,"con":29,"climb":22,"jump":22,"durationRounds":12,"notWindedAfterward":true},"challengeRating":"not explicitly printed for this sample; intentionally not invented","revision3_5":{"quasiDeityTraits":{"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"immortal":true},"coldSubtype":"Use revised Monster Manual cold subtype/vulnerability rules.","barbarianIfApplyingPrintedBbn20":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRageImprovement":"+2 additional Str/Con and +1 Will compared with old greater-rage values","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"defunctSkills":["Intuit Direction migrated","Wilderness Lore -> Survival"]}}'),

('dd-muspelheim-fire-giant-sample','Muspelheim Fire Giant Sample','200-201',
 'The printed divine-rank-0 Muspelheim fire-giant combat example. The source does not provide an explicit CR for this individual block.',
 '["deities-and-demigods","asgardian","monster-stat-block","fire-giant","muspelheim","quasi-deity","revision-3.5"]',
 '{"divineRank":0,"printedClass":"Ftr20","sourceClassHdAnomaly":"The printed header says Ftr20 while the block contains only 20d8 Hit Dice rather than adding 20 fighter d10s; preserve the source presentation without fabricating additional HD.","creature":{"type":"outsider","sourceSubtypes":["evil","fire","lawful"],"size":"Gargantuan","hitDice":"20d8+123","hitPoints":213,"initiative":3,"speedFeet":120,"armorClass":18,"touchAc":5,"flatFootedAc":18,"spaceFeet":20,"reachFeet":20},"attacks":{"greatsword":"+27/+22/+17/+12 melee, Huge masterwork greatsword","greatswordDamage":"2d8+11/19-20","rock":"+16/+11/+6/+1 ranged","rockDamage":"2d6+9 plus 2d6 fire"},"specialAttacks":["rock throwing"],"specialQualities":["printed DR 35/+4","darkvision 60 ft.","quasi-deity traits","fire subtype","rock catching"],"saves":{"fort":20,"ref":13,"will":14},"abilities":{"str":29,"dex":9,"con":23,"int":10,"wis":10,"cha":12},"skills":{"Climb":39,"Craft (stoneworking)":32,"Handle Animal":13,"Hide":-13,"Intimidate":21,"Intuit Direction":20,"Jump":39,"Listen":22,"Ride (horse)":1,"Spot":22,"Wilderness Lore":22},"feats":["Alertness","Cleave","Combat Reflexes","Endurance","Great Cleave","Great Fortitude","Improved Bull Rush","Improved Critical (greatsword)","Improved Critical (rock)","Improved Initiative","Iron Will","Lightning Reflexes","Martial Weapon Proficiency (greatsword)","Power Attack","Quick Draw","Run","Skill Focus (Craft [metalworking])","Skill Focus (Wilderness Lore)","Skill Focus (Handle Animal)","Sunder","Toughness","Weapon Focus (greatsword)","Weapon Focus (rock)","Weapon Specialization (greatsword)"],"alignment":"LE","challengeRating":"not explicitly printed for this sample; intentionally not invented","revision3_5":{"quasiDeityTraits":{"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"immortal":true},"fireSubtype":"Fire immunity comes from the fire subtype and remains separate from the revised quasi-deity fire resistance value.","fighter":"No class-feature change in the official revision if the printed Ftr20 designation is used.","defunctSkills":["Intuit Direction migrated","Wilderness Lore -> Survival"]}}'),

('dd-valkyrie-sample','Valkyrie','200-201',
 'A female divine-rank-0 Asgardian battle-servant: mechanically a human 20th-level paladin with the einherjar template and a celestial pegasus special mount.',
 '["deities-and-demigods","asgardian","monster-stat-block","valkyrie","einherjar","quasi-deity","revision-3.5"]',
 '{"divineRank":0,"gender":"female","class":"Paladin 20","template":"Einherjar","creature":{"type":"outsider","subtypes":["good"],"size":"Medium","hitDice":"20d8+140","hitPoints":230,"initiative":19,"speedFeet":60,"armorClass":35,"touchAc":16,"flatFootedAc":29},"attacks":{"heavyLance":"+30/+25/+20/+15 melee, 1d8+9/19-20/x3","halfspear":"+30/+25/+20/+15 melee, 1d6+9/19-20/x3","longsword":"+30/+25/+20/+15 melee, 1d8+9/18-20"},"specialAttacks":{"printedSmiteEvil":{"usesPerDay":1,"attackBonus":7,"damageBonus":20},"turnUndeadUsesPerDay":10,"turnUndeadEffectiveClericLevel":18},"specialQualities":["aura of courage","detect evil at will","divine grace","divine health","empathic link with mount","pegasus mount","lay on hands 140 hp/day","remove disease 6/week","share spells with mount","quasi-deity traits"],"saves":{"fort":19,"ref":29,"will":19},"abilities":{"str":28,"dex":40,"con":25,"int":24,"wis":24,"cha":24},"skills":{"Climb":34,"Concentration":50,"Diplomacy":50,"Handle Animal":50,"Heal":50,"Intimidate":30,"Jump":34,"Knowledge (arcana)":27,"Knowledge (history)":27,"Knowledge (nobility and royalty)":27,"Knowledge (the planes)":27,"Knowledge (religion)":33,"Knowledge (undead)":32,"Listen":29,"Ride (horse)":62,"Spot":32,"Swim":31},"feats":["Alertness","Cleave","Great Cleave","Improved Critical (halfspear)","Improved Critical (heavy lance)","Improved Critical (longsword)","Improved Initiative","Lightning Reflexes","Mounted Combat","Power Attack","Quick Draw","Ride-By Attack","Run","Spirited Charge","Sunder","Trample","Weapon Focus (halfspear)","Weapon Focus (heavy lance)","Weapon Focus (longsword)"],"alignment":"LG","spellcasting":{"paladinSpellsPerDay":"5/5/5/4","baseDc":"17 + spell level"},"organization":"Serves the Asgardian pantheon; all valkyries are female.","mount":"Celestial pegasus with the normal benefits of a paladin special mount.","challengeRating":"not explicitly printed for this sample; intentionally not invented","revision3_5":{"quasiDeityTraits":{"damageReduction":"10/epic","fireResistance":5,"spellResistance":32,"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"immortal":true},"paladin":{"smiteEvilUsesPerDay":5,"specialMount":"Summoned under revised paladin rules rather than permanently present."},"defunctSkills":["Knowledge (undead) ranks reassigned"],"weaponNaming":"halfspear is 3.0 terminology; preserve source name in printed stat block and map to the appropriate revised spear weapon when executing 3.5 rules."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.summary,
       'Use the structured mechanics payload. Preserve printed 3.0 statistics for source fidelity and apply revision3_5 where present for revised-game execution.',
       0,NULL,1,
       CASE WHEN d.slug='dd-template-einherjar' THEN 'monster-template' ELSE 'monster' END,
       CASE WHEN d.slug='dd-template-einherjar' THEN 'subsystem' ELSE 'stat-block' END,
       0,1,'dd-asgardian-pantheon',NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);